export interface User {
  id: number;
  name: string;
  email: string;
  role: string;
}

import type { User } from './types';

export const initialUsers: User[] = [
  {
    id: 1,
    name: 'Alice Johnson',
    email: 'alice.johnson@example.com',
    role: 'Admin',
  },
  {
    id: 2,
    name: 'Bob Smith',
    email: 'bob.smith@example.com',
    role: 'Editor',
  },
  {
    id: 3,
    name: 'Charlie Davis',
    email: 'charlie.davis@example.com',
    role: 'Viewer',
  },
  {
    id: 4,
    name: 'Dana Wright',
    email: 'dana.wright@example.com',
    role: 'Editor',
  },
];

export const ROLES = ['Admin', 'Editor', 'Viewer'] as const;

import { useForm } from '@tanstack/react-form';
import type { User } from './types';
import { ROLES } from './data';

interface EditableRowProps {
  user: User;
  onSave: (user: User) => void;
  onCancel: () => void;
}

// RFC5322 simplified email regex suitable for form validation
const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export function EditableRow({ user, onSave, onCancel }: EditableRowProps) {
  const form = useForm({
    defaultValues: {
      name: user.name,
      email: user.email,
      role: user.role,
    },
    onSubmit: ({ value }) => {
      onSave({
        id: user.id,
        name: value.name,
        email: value.email,
        role: value.role,
      });
    },
  });

  return (
    <tr className="editable-row">
      <td>{user.id}</td>
      <td>
        <form.Field
          name="name"
          validators={{
            onChange: ({ value }) =>
              !value || value.trim().length === 0
                ? 'Name is required'
                : undefined,
            onBlur: ({ value }) =>
              !value || value.trim().length === 0
                ? 'Name is required'
                : undefined,
          }}
        >
          {(field) => (
            <div className="field-wrapper">
              <input
                type="text"
                value={field.state.value}
                onChange={(e) => field.handleChange(e.target.value)}
                onBlur={field.handleBlur}
                aria-label="Name"
                className={
                  field.state.meta.errors.length > 0 ? 'input-error' : ''
                }
              />
              {field.state.meta.errors.length > 0 && (
                <div className="error-message">
                  {String(field.state.meta.errors[0])}
                </div>
              )}
            </div>
          )}
        </form.Field>
      </td>
      <td>
        <form.Field
          name="email"
          validators={{
            onChange: ({ value }) => {
              if (!value || value.trim().length === 0) {
                return 'Email is required';
              }
              if (!EMAIL_REGEX.test(value)) {
                return 'Email must be a valid format';
              }
              return undefined;
            },
            onBlur: ({ value }) => {
              if (!value || value.trim().length === 0) {
                return 'Email is required';
              }
              if (!EMAIL_REGEX.test(value)) {
                return 'Email must be a valid format';
              }
              return undefined;
            },
          }}
        >
          {(field) => (
            <div className="field-wrapper">
              <input
                type="email"
                value={field.state.value}
                onChange={(e) => field.handleChange(e.target.value)}
                onBlur={field.handleBlur}
                aria-label="Email"
                className={
                  field.state.meta.errors.length > 0 ? 'input-error' : ''
                }
              />
              {field.state.meta.errors.length > 0 && (
                <div className="error-message">
                  {String(field.state.meta.errors[0])}
                </div>
              )}
            </div>
          )}
        </form.Field>
      </td>
      <td>
        <form.Field name="role">
          {(field) => (
            <select
              value={field.state.value}
              onChange={(e) => field.handleChange(e.target.value)}
              onBlur={field.handleBlur}
              aria-label="Role"
            >
              {ROLES.map((role) => (
                <option key={role} value={role}>
                  {role}
                </option>
              ))}
            </select>
          )}
        </form.Field>
      </td>
      <td>
        <div className="action-buttons">
          <form.Subscribe
            selector={(state) => ({
              canSubmit: state.canSubmit,
              isSubmitting: state.isSubmitting,
            })}
          >
            {({ canSubmit, isSubmitting }) => (
              <button
                type="button"
                className="btn-save"
                disabled={!canSubmit || isSubmitting}
                onClick={() => form.handleSubmit()}
              >
                {isSubmitting ? 'Saving...' : 'Save'}
              </button>
            )}
          </form.Subscribe>
          <button
            type="button"
            className="btn-cancel"
            onClick={onCancel}
            disabled={form.state.isSubmitting}
          >
            Cancel
          </button>
        </div>
      </td>
    </tr>
  );
}

import { useMemo, useState } from 'react';
import {
  createColumnHelper,
  flexRender,
  getCoreRowModel,
  useReactTable,
  type ColumnDef,
} from '@tanstack/react-table';
import { initialUsers } from './data';
import type { User } from './types';
import { EditableRow } from './EditableRow';
import './App.css';

function App() {
  const [data, setData] = useState<User[]>(() => initialUsers);
  const [editingId, setEditingId] = useState<number | null>(null);

  const columns = useMemo<ColumnDef<User, unknown>[]>(
    () => [
      {
        accessorKey: 'id',
        header: 'ID',
        cell: (info) => info.getValue<number>(),
      },
      {
        accessorKey: 'name',
        header: 'Name',
        cell: (info) => info.getValue<string>(),
      },
      {
        accessorKey: 'email',
        header: 'Email',
        cell: (info) => info.getValue<string>(),
      },
      {
        accessorKey: 'role',
        header: 'Role',
        cell: (info) => info.getValue<string>(),
      },
      {
        id: 'actions',
        header: 'Actions',
        cell: ({ row }) => (
          <button
            type="button"
            className="btn-edit"
            onClick={() => setEditingId(row.original.id)}
            disabled={editingId !== null}
          >
            Edit
          </button>
        ),
      },
    ],
    [editingId],
  );

  // Silence unused-variable warning for the createColumnHelper helper;
  // we rely on the inferred ColumnDef type above for portability.
  void createColumnHelper<User>();

  const table = useReactTable({
    data,
    columns,
    getCoreRowModel: getCoreRowModel(),
  });

  const handleSave = (updatedUser: User) => {
    setData((prev) =>
      prev.map((user) => (user.id === updatedUser.id ? updatedUser : user)),
    );
    setEditingId(null);
  };

  const handleCancel = () => {
    setEditingId(null);
  };

  return (
    <div className="app">
      <header className="app-header">
        <h1>Users</h1>
        <p className="app-subtitle">
          Click the <strong>Edit</strong> button on a row to update its fields
          inline. Powered by TanStack Table &amp; TanStack Form.
        </p>
      </header>
      <main className="app-main">
        <div className="table-wrapper">
          <table className="data-table">
            <thead>
              {table.getHeaderGroups().map((headerGroup) => (
                <tr key={headerGroup.id}>
                  {headerGroup.headers.map((header) => (
                    <th key={header.id}>
                      {header.isPlaceholder
                        ? null
                        : flexRender(
                            header.column.columnDef.header,
                            header.getContext(),
                          )}
                    </th>
                  ))}
                </tr>
              ))}
            </thead>
            <tbody>
              {table.getRowModel().rows.map((row) => {
                const user = row.original;
                const isEditing = editingId === user.id;
                if (isEditing) {
                  return (
                    <EditableRow
                      key={row.id}
                      user={user}
                      onSave={handleSave}
                      onCancel={handleCancel}
                    />
                  );
                }
                return (
                  <tr key={row.id}>
                    {row.getVisibleCells().map((cell) => (
                      <td key={cell.id}>
                        {flexRender(
                          cell.column.columnDef.cell,
                          cell.getContext(),
                        )}
                      </td>
                    ))}
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </main>
    </div>
  );
}

export default App;

